from app.services import users


def _parse_positive_int(raw) -> int | None:
    """Parse a string of ASCII digits into an int, or return None when invalid."""
    if not isinstance(raw, str) or not raw.isascii() or not raw.isdigit():
        return None
    return int(raw)


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_users_page(params: dict) -> tuple[int, dict]:
    page = _parse_positive_int(params.get("page", "1"))
    page_size = _parse_positive_int(params.get("page_size", "10"))
    if page is None or page < 1 or page_size is None or not 1 <= page_size <= 50:
        return 400, {"error": "invalid paging"}
    page_users, total = users.list_users(page, page_size)
    return 200, {"users": page_users, "page": page, "page_size": page_size, "total": total}
"}

